ALTER TABLE "patients" ADD CONSTRAINT "patients_tenant_id_unique" UNIQUE ("tenant_id", "id");
ALTER TABLE "patient_pending_operations" DROP CONSTRAINT IF EXISTS "patient_pending_operations_patient_id_fkey";
ALTER TABLE "patient_pending_operations" ADD CONSTRAINT "patient_pending_operations_tenant_patient_fk" FOREIGN KEY ("tenant_id", "patient_id") REFERENCES "patients"("tenant_id", "id");
CREATE TABLE IF NOT EXISTS "procedures" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"), "name" text NOT NULL, "description" text, "base_sessions" integer, "duration_minutes" integer NOT NULL DEFAULT 60, "standalone" boolean NOT NULL DEFAULT true, "price_cents" integer NOT NULL DEFAULT 0, "session_schema" jsonb NOT NULL, "active" boolean NOT NULL DEFAULT true, "require_new_anamnesis" boolean NOT NULL DEFAULT false, "current_version" integer NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("tenant_id", "id"), CHECK (length(trim("name")) >= 2), CHECK ("duration_minutes" BETWEEN 1 AND 1440), CHECK ("price_cents" >= 0), CHECK ("base_sessions" IS NULL OR "base_sessions" >= 1));
CREATE INDEX IF NOT EXISTS "procedures_tenant_active_idx" ON "procedures" ("tenant_id", "active");
CREATE TABLE IF NOT EXISTS "procedure_versions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "procedure_id" uuid NOT NULL, "version" integer NOT NULL, "session_schema" jsonb NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), FOREIGN KEY ("tenant_id", "procedure_id") REFERENCES "procedures"("tenant_id", "id"), UNIQUE("tenant_id", "procedure_id", "version"));
CREATE TABLE IF NOT EXISTS "anamneses" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"), "title" text NOT NULL, "active" boolean NOT NULL DEFAULT true, "required_by_default" boolean NOT NULL DEFAULT true, "validity_months" integer NOT NULL DEFAULT 12, "current_version" integer NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("tenant_id", "id"), CHECK (length(trim("title")) >= 2), CHECK ("validity_months" >= 1));
CREATE TABLE IF NOT EXISTS "anamnesis_versions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "anamnesis_id" uuid NOT NULL, "version" integer NOT NULL, "schema" jsonb NOT NULL, "origin" text NOT NULL DEFAULT 'created', "restored_from_version" integer, "created_at" timestamptz NOT NULL DEFAULT now(), FOREIGN KEY ("tenant_id", "anamnesis_id") REFERENCES "anamneses"("tenant_id", "id"), UNIQUE("tenant_id", "anamnesis_id", "version"), CHECK ("origin" IN ('created','edited','restored')), CHECK ("origin" <> 'restored' OR "restored_from_version" IS NOT NULL));
CREATE TABLE IF NOT EXISTS "anamnesis_procedures" ("tenant_id" uuid NOT NULL, "anamnesis_id" uuid NOT NULL, "procedure_id" uuid NOT NULL, "required" boolean NOT NULL DEFAULT true, PRIMARY KEY ("tenant_id", "anamnesis_id", "procedure_id"), FOREIGN KEY ("tenant_id", "anamnesis_id") REFERENCES "anamneses"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "procedure_id") REFERENCES "procedures"("tenant_id", "id"));
CREATE TABLE IF NOT EXISTS "combos" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"), "name" text NOT NULL, "description" text, "price_cents" integer NOT NULL, "promotional_price_cents" integer, "valid_from" timestamptz, "valid_until" timestamptz, "active" boolean NOT NULL DEFAULT true, "require_new_anamnesis" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("tenant_id", "id"), CHECK (length(trim("name")) >= 2), CHECK ("price_cents" >= 0 AND ("promotional_price_cents" IS NULL OR ("promotional_price_cents" >= 0 AND "promotional_price_cents" <= "price_cents"))), CHECK ("valid_until" IS NULL OR "valid_from" IS NULL OR "valid_until" >= "valid_from"));
CREATE TABLE IF NOT EXISTS "combo_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "combo_id" uuid NOT NULL, "procedure_id" uuid NOT NULL, "sessions" integer NOT NULL, "price_override_cents" integer, FOREIGN KEY ("tenant_id", "combo_id") REFERENCES "combos"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "procedure_id") REFERENCES "procedures"("tenant_id", "id"), UNIQUE("tenant_id", "combo_id", "procedure_id"), CHECK ("sessions" >= 1), CHECK ("price_override_cents" IS NULL OR "price_override_cents" >= 0));
CREATE TABLE IF NOT EXISTS "contracts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"), "title" text NOT NULL, "kind" text NOT NULL, "procedure_id" uuid, "combo_id" uuid, "active" boolean NOT NULL DEFAULT true, "current_version" integer NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("tenant_id", "id"), FOREIGN KEY ("tenant_id", "procedure_id") REFERENCES "procedures"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "combo_id") REFERENCES "combos"("tenant_id", "id"), CHECK ("kind" IN ('standard','procedure','combo')), CHECK (("kind"='standard' AND "procedure_id" IS NULL AND "combo_id" IS NULL) OR ("kind"='procedure' AND "procedure_id" IS NOT NULL AND "combo_id" IS NULL) OR ("kind"='combo' AND "combo_id" IS NOT NULL AND "procedure_id" IS NULL)));
CREATE TABLE IF NOT EXISTS "contract_versions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "contract_id" uuid NOT NULL, "version" integer NOT NULL, "content" text, "source_object_key" text, "origin" text NOT NULL DEFAULT 'created', "restored_from_version" integer, "created_at" timestamptz NOT NULL DEFAULT now(), FOREIGN KEY ("tenant_id", "contract_id") REFERENCES "contracts"("tenant_id", "id"), UNIQUE("tenant_id", "contract_id", "version"), CHECK ("origin" IN ('created','edited','restored')), CHECK ("content" IS NOT NULL OR "source_object_key" IS NOT NULL));
CREATE TABLE IF NOT EXISTS "plans" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL REFERENCES "tenants"("id"), "name" text NOT NULL, "description" text, "active" boolean NOT NULL DEFAULT true, "current_version" integer NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), UNIQUE("tenant_id", "id"), CHECK (length(trim("name")) >= 2));
CREATE TABLE IF NOT EXISTS "plan_versions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "plan_id" uuid NOT NULL, "version" integer NOT NULL, "price_cents" integer NOT NULL, "duration_days" integer, "validity_days" integer, "require_new_anamnesis" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), FOREIGN KEY ("tenant_id", "plan_id") REFERENCES "plans"("tenant_id", "id"), UNIQUE("tenant_id", "plan_id", "version"), CHECK ("price_cents" >= 0), CHECK ("duration_days" IS NULL OR "duration_days" >= 1), CHECK ("validity_days" IS NULL OR "validity_days" >= 1));
ALTER TABLE "plan_versions" ADD CONSTRAINT "plan_versions_tenant_id_unique" UNIQUE ("tenant_id", "id");
CREATE TABLE IF NOT EXISTS "plan_version_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_id" uuid NOT NULL, "plan_version_id" uuid NOT NULL, "procedure_id" uuid NOT NULL, "sessions" integer NOT NULL, "procedure_name" text NOT NULL, "duration_minutes" integer NOT NULL, "price_cents" integer NOT NULL, "session_schema" jsonb NOT NULL, FOREIGN KEY ("tenant_id", "plan_version_id") REFERENCES "plan_versions"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "procedure_id") REFERENCES "procedures"("tenant_id", "id"), CHECK ("sessions" >= 1), CHECK ("duration_minutes" >= 1), CHECK ("price_cents" >= 0));
CREATE TABLE IF NOT EXISTS "plan_version_contracts" ("tenant_id" uuid NOT NULL, "plan_version_id" uuid NOT NULL, "contract_id" uuid NOT NULL, "contract_version" integer NOT NULL, "title" text NOT NULL, "content_snapshot" text, "source_object_key" text, PRIMARY KEY ("tenant_id", "plan_version_id", "contract_id"), FOREIGN KEY ("tenant_id", "plan_version_id") REFERENCES "plan_versions"("tenant_id", "id"), FOREIGN KEY ("tenant_id", "contract_id") REFERENCES "contracts"("tenant_id", "id"), CHECK ("contract_version" >= 1));
CREATE INDEX IF NOT EXISTS "catalog_tenant_created_idx" ON "procedures" ("tenant_id", "created_at");
INSERT INTO "tenants" ("id", "name") VALUES ('00000000-0000-0000-0000-000000000001', 'Clínicare') ON CONFLICT ("id") DO NOTHING;
